import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"AppleSkinPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/apple-skin-pumpkin/docs/index.md"},"headers":[],"relativePath":"packages/apple-skin-pumpkin/docs/index.md","filePath":"packages/apple-skin-pumpkin/docs/index.md","lastUpdated":1792508976000}`),l={name:`packages/apple-skin-pumpkin/docs/index.md`},u={id:`appleskinpumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/apple-skin-pumpkin-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/apple-skin-pumpkin/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`AppleSkinPumpkin `),n(`a`,{class:`header-anchor`,href:`#appleskinpumpkin`,"aria-label":`Permalink to “AppleSkinPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[2]||=r(`<p>AppleSkinPumpkin keeps AppleSkin&#39;s hunger HUD in sync with the server. It sends Java Edition clients their saturation and exhaustion values, along with whether their world uses natural health regeneration. Players still need the AppleSkin client mod; this plugin supplies the server-side values it needs.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><p>Place <code>apple-skin-pumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory, then restart the server. On first load, Pumpkin asks for the plugin&#39;s permissions in the server console. Hot reload can&#39;t show that prompt.</p><h2 id="what-clients-receive" tabindex="-1">What clients receive <a class="header-anchor" href="#what-clients-receive" aria-label="Permalink to “What clients receive”">​</a></h2><p>At the end of each server tick, the plugin checks every online player and sends updated values when saturation changes or exhaustion moves far enough to matter. Vanilla doesn&#39;t regularly send these values in the form AppleSkin needs, so the plugin sends them directly. It also tells AppleSkin whether natural health regeneration is enabled in the player&#39;s world. Bedrock players are skipped because AppleSkin is a Java Edition mod.</p><h2 id="diagnose-updates" tabindex="-1">Diagnose updates <a class="header-anchor" href="#diagnose-updates" aria-label="Permalink to “Diagnose updates”">​</a></h2><p>Set <code>logging.level</code> to <code>debug</code> in the Pumpkin server configuration to see the values sent and when players join, leave, or are skipped. After a line for the first tick, ticks without updates stay quiet. The plugin has no separate configuration file or player commands.</p>`,7)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};